//! Frozen resolved descriptions; expected values come from the public typed catalog.
//! Peer TLS, HTTP/2 and navigation values also match the pinned peer sources
//! and raw observations under `phantom-profile/tests/fixtures/peers`.
use super::super::import_profile_json;
use phantom_profile::catalog::{self, RequestTemplateKind};
use std::error::Error;

pub(super) type TestResult = Result<(), Box<dyn Error>>;

pub(super) fn document(index: usize) -> Result<serde_json::Value, Box<dyn Error>> {
    Ok(serde_json::from_str(PROFILES[index].1)?)
}
pub(super) fn import(
    value: &serde_json::Value,
) -> Result<phantom_profile::ClientProfile, Box<dyn Error>> {
    Ok(import_profile_json(&serde_json::to_vec(value)?)?)
}

#[test]
fn all_catalog_base_profiles_preserve_every_typed_value_and_absence() -> TestResult {
    assert_eq!(PROFILES.len(), 20);
    assert_eq!(catalog::profiles().len(), PROFILES.len());
    for definition in catalog::profiles() {
        let id = definition.id().as_str();
        assert_eq!(
            PROFILES
                .iter()
                .filter(|(candidate, _)| *candidate == id)
                .count(),
            1,
            "{id}"
        );
    }
    for &(id, json) in PROFILES {
        assert_eq!(
            import_profile_json(json.as_bytes())?,
            catalog::profile(id)?.instantiate(&[])?,
            "{id}"
        );
    }
    Ok(())
}

#[test]
fn exported_contexts_are_owned_without_importing_catalog_identity() -> TestResult {
    let original = catalog::profile("chrome-154-windows")?.instantiate(&[])?;
    let exported = super::super::export_profile_json(&original)?;
    let imported = super::super::import_profile_json(&exported)?;
    assert_eq!(original, imported);
    assert_eq!(super::super::export_profile_json(&imported)?, exported);
    assert!(original.request_context_profile().is_some());
    assert!(imported.request_context_profile().is_none());
    let client = crate::Client::builder(imported).build()?;
    client
        .get("https://example.test/")?
        .context(RequestTemplateKind::Navigation)?;
    Ok(())
}

#[test]
fn explicit_tcp_port_randomization_survives_import_and_export() -> TestResult {
    use phantom_profile::TcpPortRandomization;

    let index = PROFILES
        .iter()
        .position(|(id, _)| *id == "chrome/154.0.8037.97/windows-11-26200/r1")
        .ok_or("Windows Chrome profile absent")?;
    let mut value = document(index)?;
    value["profile"]["tcp"]["port_randomization"] =
        serde_json::json!({"minimum_windows_build": 22621});

    let imported = import(&value)?;
    assert_eq!(
        imported
            .tcp()
            .ok_or("TCP settings absent")?
            .port_randomization,
        Some(TcpPortRandomization {
            minimum_windows_build: 22621,
        })
    );

    let exported = super::super::export_profile_json(&imported)?;
    let exported_value: serde_json::Value = serde_json::from_slice(&exported)?;
    assert_eq!(
        exported_value["profile"]["tcp"]["port_randomization"],
        value["profile"]["tcp"]["port_randomization"]
    );
    assert_eq!(super::super::import_profile_json(&exported)?, imported);
    Ok(())
}

#[test]
fn retained_template_exports_preserve_fields_flags_priority_and_protocol_absences() -> TestResult {
    assert_eq!(TEMPLATES.len(), 44);
    for definition in catalog::profiles() {
        let id = definition.id().as_str();
        for kind in [
            RequestTemplateKind::Navigation,
            RequestTemplateKind::FetchNoStore,
            RequestTemplateKind::Fetch,
            RequestTemplateKind::FetchUpload,
        ] {
            let fixtures = TEMPLATES
                .iter()
                .filter(|(candidate, candidate_kind, _)| {
                    *candidate == id && *candidate_kind == kind
                })
                .count();
            assert_eq!(
                fixtures,
                usize::from(definition.request_template(kind).is_ok()),
                "{id} {kind:?}"
            );
        }
    }
    for &(id, kind, json) in TEMPLATES {
        let index = PROFILES
            .iter()
            .position(|(candidate, _)| *candidate == id)
            .ok_or("fixture profile absent")?;
        let mut value = document(index)?;
        value["profile"]["request_template"] = serde_json::from_str(json)?;
        let expected = catalog::profile(id)?
            .instantiate(&[])?
            .with_request_template(catalog::profile(id)?.request_template(kind)?);
        assert_eq!(import(&value)?, expected, "{id} {kind:?}");
    }
    Ok(())
}

#[test]
fn alt_used_import_keeps_all_typed_policies_and_rejects_unknown_values() -> TestResult {
    use phantom_profile::Http3AltUsed;
    let mut value = document(0)?;
    for (name, expected) in [
        ("Omit", Http3AltUsed::Omit),
        ("Append", Http3AltUsed::Append),
        ("ValidatedMapping", Http3AltUsed::ValidatedMapping),
    ] {
        value["profile"]["http3"]["request"]["alt_used"] = name.into();
        let imported = import(&value)?;
        assert_eq!(
            imported
                .http3()
                .ok_or("HTTP/3 settings absent")?
                .request()
                .alt_used,
            expected
        );
    }
    for unsupported in [
        serde_json::json!("FirstStream"),
        serde_json::json!(true),
        serde_json::json!({"kind":"ValidatedMapping"}),
    ] {
        value["profile"]["http3"]["request"]["alt_used"] = unsupported;
        assert!(import(&value).is_err());
    }
    Ok(())
}

#[test]
fn alt_used_port_import_roundtrips_and_requires_an_explicit_typed_field() -> TestResult {
    use phantom_profile::Http3AltUsedPort;
    let mut value = document(0)?;
    for (name, expected) in [
        ("Explicit", Http3AltUsedPort::Explicit),
        ("OmitDefault", Http3AltUsedPort::OmitDefault),
    ] {
        value["profile"]["http3"]["request"]["alt_used_port"] = name.into();
        let imported = import(&value)?;
        assert_eq!(
            imported
                .http3()
                .ok_or("HTTP/3 settings absent")?
                .request()
                .alt_used_port,
            expected
        );
        let exported = super::super::export_profile_json(&imported)?;
        let roundtrip = super::super::import_profile_json(&exported)?;
        assert_eq!(roundtrip, imported);
    }
    for unsupported in [
        serde_json::json!("SchemeDefault"),
        serde_json::json!(true),
        serde_json::json!(null),
        serde_json::json!({"kind":"Explicit"}),
    ] {
        value["profile"]["http3"]["request"]["alt_used_port"] = unsupported;
        assert!(import(&value).is_err());
    }
    value["profile"]["http3"]["request"]
        .as_object_mut()
        .ok_or("request object absent")?
        .remove("alt_used_port");
    assert!(
        import(&value).is_err(),
        "missing policy must not be inferred from emission or browser identity"
    );
    Ok(())
}

#[test]
fn alt_used_import_accepts_only_the_typed_http3_unit_slot() -> TestResult {
    let mut value = document(0)?;
    let template = serde_json::json!({
        "http1_fields": [], "http2_fields": [],
        "http3_fields": [{"variant": "AltUsed"}], "http2_priority": null,
        "requested_client_hint_placement": false,
        "restarts_for_connection_accept_ch": false
    });
    value["profile"]["request_template"] = template.clone();
    let imported = import(&value)?;
    assert_eq!(
        imported
            .request_template()
            .and_then(|template| template.http3_fields.as_deref()),
        Some([phantom_profile::RequestField::AltUsed].as_slice())
    );
    for malformed in [
        serde_json::json!({"variant": "AltUsed", "name": "alt-used"}),
        serde_json::json!({"variant": "AltUsed", "value": "spoofed"}),
        serde_json::json!({"variant": "Literal", "name": "alt-used", "value": "spoofed"}),
        serde_json::json!({"variant": "Caller", "name": "alt-used", "required": false}),
    ] {
        value["profile"]["request_template"] = template.clone();
        value["profile"]["request_template"]["http3_fields"][0] = malformed;
        assert!(import(&value).is_err());
    }
    for name in ["http1_fields", "http2_fields"] {
        value["profile"]["request_template"] = template.clone();
        value["profile"]["request_template"][name] = serde_json::json!([{"variant": "AltUsed"}]);
        assert!(import(&value).is_err());
    }
    value["profile"]["request_template"] = template;
    value["profile"]["request_template"]["http3_fields"] =
        serde_json::json!([{"variant": "AltUsed"}, {"variant": "AltUsed"}]);
    assert!(import(&value).is_err());
    Ok(())
}

#[test]
fn imported_profiles_own_their_storage_after_input_is_dropped() -> TestResult {
    let mut bytes = PROFILES[0].1.as_bytes().to_vec();
    let profile = import_profile_json(&bytes)?;
    bytes.fill(0);
    drop(bytes);
    assert_eq!(profile, catalog::profile(PROFILES[0].0)?.instantiate(&[])?);
    Ok(())
}

#[test]
fn pinned_firefox_grease_bundles_do_not_follow_the_new_catalog_revision() -> TestResult {
    use super::super::{ProfileBundle, describe_profile, export_profile_json};
    use phantom_profile::{EchGreaseAead, EchGreasePayloadLength, EchGreaseSettings, EchSettings};

    let index = PROFILES
        .iter()
        .position(|(id, _)| *id == "firefox/157.0/windows-11-26200/r2")
        .ok_or("Firefox profile absent")?;
    let mut legacy = document(index)?;
    legacy["profile"]["tls"]["ech"]["kind"] = "Grease".into();
    let bytes = serde_json::to_vec(&serde_json::json!({
        "format": "phantom.profile-bundle",
        "version": 1,
        "id": "pinned/firefox",
        "revision": 1,
        "profiles": [{"name": "firefox/157-r1", "document": legacy, "provenance": []}]
    }))?;
    let bundle = ProfileBundle::from_json(&bytes)?;
    drop(bytes);
    let restored = bundle
        .profiles()
        .get("firefox/157-r1")
        .ok_or("profile absent")?;
    assert_eq!(
        restored.tls().ech,
        EchSettings::Grease(EchGreaseSettings::new(
            EchGreasePayloadLength::FromClientHello {
                maximum_name_length: 100
            },
            vec![EchGreaseAead::Aes128Gcm, EchGreaseAead::ChaCha20Poly1305],
        )?)
    );
    let exported = describe_profile(restored)?;
    assert_eq!(exported["version"], 2);
    assert_eq!(
        exported["profile"]["request_contexts"],
        serde_json::json!({})
    );
    let mut expected = legacy;
    expected["version"] = 2.into();
    expected["profile"]["request_contexts"] = serde_json::json!({});
    assert_eq!(exported, expected);
    assert_eq!(
        import_profile_json(&export_profile_json(restored)?)?,
        *restored
    );
    assert_ne!(
        restored,
        &catalog::profile(PROFILES[index].0)?.instantiate(&[])?
    );
    Ok(())
}

#[test]
fn pinned_firefox_r2_bundle_retains_its_socks_feedback() -> TestResult {
    use super::super::{ProfileBundle, describe_profile, export_profile_json};
    use phantom_profile::{SocksProxyDnsFeedback, TcpAddressSelection, browser::firefox};

    let r2 = catalog::profile("firefox/157.0/windows-11-26200/r2")?.instantiate(&[])?;
    assert_eq!(r2, firefox::v157_windows_r2());
    let document = describe_profile(&r2)?;
    let bytes = serde_json::to_vec(&serde_json::json!({
        "format": "phantom.profile-bundle", "version": 1,
        "id": "pinned/firefox", "revision": 2,
        "profiles": [{"name": "firefox/r2", "document": document, "provenance": []}]
    }))?;
    let bundle = ProfileBundle::from_json(&bytes)?;
    let restored = bundle
        .profiles()
        .get("firefox/r2")
        .ok_or("pinned profile missing")?;
    assert_eq!(restored, &r2);
    assert_eq!(import_profile_json(&export_profile_json(restored)?)?, r2);
    assert_ne!(restored, &firefox::v157_windows());
    for (recipe, expected) in [
        (restored.clone(), SocksProxyDnsFeedback::AllConnectFailures),
        (
            firefox::v157_windows(),
            SocksProxyDnsFeedback::InitialConnectFailures,
        ),
    ] {
        let TcpAddressSelection::Backup(backup) =
            recipe.tcp().ok_or("TCP policy missing")?.address_selection
        else {
            return Err("backup policy missing".into());
        };
        assert_eq!(backup.socks_proxy_dns_feedback, expected);
    }
    Ok(())
}

